general.scss:
$black:  #0f0f0f;
$white:  #ffffff;
$red:  #E82222;
$green: #08BC72;
$grey:  #868686;
$darkgrey: #787878;



.body, .modal{
    .breadcrumbs{
        margin-top: 0.5rem;
        margin-bottom: 0.75rem;
        .breadcrumb {
            font-size: 13px;
            font-weight: 400;
            color: $darkgrey;
        }
        .breadcrumb.is-active{

        }
    }

    /* width */
    ::-webkit-scrollbar {
        width: 5px;
        height: 10px;
    }

    /* Track */
    ::-webkit-scrollbar-track {
        background: #d9d9d9;
        border-radius: 15px;
    }

    /* Handle */
    ::-webkit-scrollbar-thumb {
        background: $black; 
        border-radius: 15px;
    }

    /* Handle on hover */
    ::-webkit-scrollbar-thumb:hover {
        background: #555; 
    }

    .button.button--primary{
        border-radius: 30px;
        text-transform: none;
    }
}

#weglot-switcher-1{
    display: none !important;
}

