@media (min-width: 800px) {

}

@media (max-width: 800px) {

    .beautify__flexBanners{
        .container{
            padding: 0;
            ._banner{
                ._imgContainer{
                    min-height: 250px;
                    img{
                        object-position: center center;
                        min-height: 250px;
                        min-width: 210px;
                    }
                }
                ._imgContainer::before{
                    display: none;
                }
                ._body{
                    position: absolute;
                    width: 100%;
                    bottom: 0;
                }
            }
        }
    }

}
div[data-layout-name="Layout6"]{
    div[data-sub-layout]{
        .beautify__flexBanners{
            .container{
                padding: 0 7px;
            }
        }
    }
}
@media (max-width: 1200px) {
    div[data-layout-name="Layout6"]{
        display: grid;
        grid-template-columns: 1fr 1fr 1fr;
        div[data-sub-layout]{
            min-width: 100%;
            margin-bottom: 19px;
            .beautify__flexBanners{
                .container{
                    padding: 0;
                    ._banner{
                        ._imgContainer{
                            min-height: 250px;
                            img{
                                object-position: center center;
                                min-height: 250px;
                                min-width: 210px;
                            }
                        }
                        ._imgContainer::before{
                            display: none;
                        }
                        ._body{
                            position: absolute;
                            width: 100%;
                            bottom: 0;
                        }
                    }
                }
            }
        }
    }
}
@media (max-width: 800px) {
    div[data-layout-name="Layout6"]{
        display: grid;
        grid-template-columns: 1fr 1fr;
        div[data-sub-layout]{
            min-width: 100%;
            margin-bottom: 12px;
            .beautify__flexBanners{
                .container{
