    }
}


@media (min-width: 800px) {

    .page_type__category{
        .category.no-filters{
            position: relative;
            nav[aria-label="Breadcrumb"]{
                position: absolute;
                z-index: 2;
                .breadcrumb-label{
                    color: $white;
                }
                .breadcrumb:not(:first-child)::before {
                    border-right: 0.1em solid $white;
                }
            }
        }
    }

    .page_type__page{
        .container.w-banner{
            position: relative;
            margin-top: -0.6rem;
            nav[aria-label="Breadcrumb"]{
                position: absolute;
                z-index: 2;
                .breadcrumbs{
                    display: block;
                }
                .breadcrumb-label{
                    color: $white;
                }
                .breadcrumb:not(:first-child)::before {
                    border-right: 0.1em solid $white;
                }
            }
        }
    }
    .page_type__category, .page_type__brand{
        .body{
            margin-top: 1.95rem;
        }
    }

}

@media (max-width: 800px) {
    .page_type__category, .page_type__brand{
        .body{
            margin-top: 2rem;
        }
        .category.no-filters{
            position: relative;
            nav[aria-label="Breadcrumb"]{
                position: absolute;
                z-index: 2;
                top: 6px;
                .breadcrumb-label{
                    color: $white;
                }
                .breadcrumb:not(:first-child)::before {
                    border-right: 0.1em solid $white;
                }
            }
            .container.description{
                margin-top: 0 !important;
            }
        }
    }

    .page_type__page{
        .container.w-banner{
            position: relative;
            margin-top: -0.3rem;
            nav[aria-label="Breadcrumb"]{
                position: absolute;
                z-index: 2;
                //top: 35px;
                .breadcrumbs{
                    display: block;
                }
                .breadcrumb-label{
                    color: $white;
                }
                .breadcrumb:not(:first-child)::before {
                    border-right: 0.1em solid $white;
                }
            }
        }
    }
}


